      const checkbox = document.getElementById("agree-terms");
      const error = document.getElementById("consent-error");
      const status = document.getElementById("form-status");

      function showError(message) {
        error.hidden = false;
        error.textContent = message;
        checkbox.setAttribute("aria-invalid", "true");
        checkbox.setAttribute("aria-describedby", "consent-help consent-error");
      }

      function clearError() {
        error.hidden = true;
        error.textContent = "Error: You must agree to the terms of use.";
        checkbox.removeAttribute("aria-invalid");
        checkbox.setAttribute("aria-describedby", "consent-help");
      }

      checkbox.addEventListener("change", () => {
        if (checkbox.checked) {
          clearError();
        }
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!checkbox.checked) {
          status.textContent = "";
          status.removeAttribute("data-state");
          showError("Error: You must agree to the terms of use.");
          checkbox.focus();
          return;
        }

        clearError();
        status.textContent = "Consent saved. You can continue.";
        status.setAttribute("data-state", "success");
      });
    </script>
  </body>
