     <meta name="viewport" content="width=device-width, initial-scale=1">
     <title>Terms Consent</title>
     <style>
       :root {
         color-scheme: light;
         --bg: #f5f7fb;
         --surface: #ffffff;
         --surface-muted: #f0f4ff;
         --text: #122033;
         --muted: #5b687f;
         --border: #d7deea;
         --accent: #325dff;
         --accent-strong: #2446c7;
         --danger: #c43d3d;
         --shadow: 0 24px 60px rgba(18, 32, 51, 0.12);
         --radius: 20px;
       }

       * {
         box-sizing: border-box;
       }

       html, body {
         min-height: 100%;
       }

       body {
         margin: 0;
         font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         line-height: 1.5;
         color: var(--text);
         background:
           radial-gradient(circle at top, rgba(50, 93, 255, 0.12), transparent 40%),
           linear-gradient(180deg, #f8faff 0%, var(--bg) 100%);
       }

       a {
         color: var(--accent-strong);
       }

       .skip-link {
         position: absolute;
         left: 1rem;
         top: 1rem;
         transform: translateY(-180%);
         padding: 0.75rem 1rem;
         border-radius: 999px;
         background: var(--surface);
         color: var(--text);
         box-shadow: var(--shadow);
         text-decoration: none;
         z-index: 10;
       }

       .skip-link:focus-visible {
         transform: translateY(0);
       }

       .page {
         min-height: 100svh;
         display: grid;
         place-items: center;
         padding: 2rem 1rem;
       }

       .card {
         width: min(100%, 40rem);
         background: var(--surface);
         border: 1px solid rgba(215, 222, 234, 0.9);
         border-radius: calc(var(--radius) + 4px);
         box-shadow: var(--shadow);
         overflow: clip;
       }

       .card__header {
         padding: 2rem 2rem 1.25rem;
         background: linear-gradient(180deg, rgba(50, 93, 255, 0.08), transparent);
         border-bottom: 1px solid rgba(215, 222, 234, 0.75);
       }

       .eyebrow {
         margin: 0 0 0.5rem;
         color: var(--accent-strong);
         font-size: 0.875rem;
         font-weight: 700;
         letter-spacing: 0.08em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0;
         font-size: clamp(1.6rem, 4vw, 2.35rem);
         line-height: 1.15;
       }

       .card__body {
         padding: 2rem;
       }

       .intro {
         margin: 0 0 1.5rem;
         color: var(--muted);
         max-width: 42ch;
       }

       .form-field {
         display: grid;
         gap: 0.55rem;
         padding: 1rem;
         border: 1px solid var(--border);
         border-radius: 16px;
         background: var(--surface-muted);
       }

       .checkbox-row {
         display: flex;
         align-items: flex-start;
         gap: 0.75rem;
       }

       .checkbox-row input {
         width: 1.125rem;
         height: 1.125rem;
         margin: 0.2rem 0 0;
         flex: none;
         accent-color: var(--accent);
       }

       .checkbox-row label {
         font-weight: 600;
         cursor: pointer;
       }

       .required-marker {
         color: var(--danger);
       }

       .help-text {
         margin: 0;
         color: var(--muted);
         font-size: 0.95rem;
       }

       .error-text {
         margin: 0;
         color: var(--danger);
         font-size: 0.95rem;
       }

       .actions {
         display: flex;
         flex-wrap: wrap;
         gap: 0.75rem;
         align-items: center;
         margin-top: 1.5rem;
       }

       button {
         appearance: none;
         border: 0;
         border-radius: 999px;
         padding: 0.9rem 1.25rem;
         background: linear-gradient(180deg, var(--accent), var(--accent-strong));
         color: #fff;
         font: inherit;
         font-weight: 700;
         box-shadow: 0 14px 26px rgba(50, 93, 255, 0.22);
         cursor: pointer;
       }

       button:hover {
         filter: brightness(1.03);
       }

       button:focus-visible,
       input:focus-visible {
         outline: 3px solid #111827;
         outline-offset: 3px;
       }

       .status {
         margin: 0;
         min-height: 1.5rem;
         color: var(--muted);
       }

       .status[data-state="success"] {
         color: #1f6f43;
       }

       @media (max-width: 30rem) {
         .page {
           padding: 1rem;
         }

         .card__header,
         .card__body {
           padding-left: 1.25rem;
           padding-right: 1.25rem;
         }
       }

       @media (forced-colors: active) {
         :root {
           --shadow: none;
         }

         .card,
         .form-field {
           border: 1px solid CanvasText;
         }

         button {
           border: 1px solid ButtonText;
         }

         .skip-link:focus-visible,
         button:focus-visible,
         input:focus-visible {
           outline-color: Highlight;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#maincontent">Skip to main content</a>
     <div id="app"></div>

     <script>
       function ConsentField() {
         return `
           <div class="form-field">
             <div class="checkbox-row">
               <input
                 id="agree-terms"
                 name="agreeTerms"
                 type="checkbox"
                 required
                 aria-describedby="consent-help">
               <label for="agree-terms">
                 I agree to the terms of use <span class="required-marker" aria-hidden="true">*</span>
               </label>
             </div>

             <p id="consent-help" class="help-text">Required to continue.</p>
             <p id="consent-error" class="error-text" hidden>Error: You must agree to the terms of use.</p>
           </div>
         `;
       }

       function ConsentForm() {
         return `
           <form id="consent-form" novalidate>
             ${ConsentField()}

             <div class="actions">
               <button type="submit">Agree and continue</button>
               <p id="form-status" class="status" role="status" aria-live="polite"></p>
             </div>
           </form>
         `;
       }

       function App() {
         return `
           <main id="maincontent" class="page" tabindex="-1">
             <section class="card" aria-labelledby="page-title">
               <header class="card__header">
                 <p class="eyebrow">Account access</p>
                 <h1 id="page-title">Agree to the terms of use</h1>
               </header>

               <div class="card__body">
                 <p class="intro">Review the consent below, then confirm to continue.</p>
                 ${ConsentForm()}
               </div>
             </section>
           </main>
         `;
       }

       document.getElementById("app").innerHTML = App();

       const form = document.getElementById("consent-form");
       const checkbox = document.getElementById("agree-terms");
       const error = document.getElementById("consent-error");
       const status = document.getElementById("form-status");

       function showError(message) {
         error.hidden = false;
         error.textContent = message;
         checkbox.setAttribute("aria-invalid", "true");
         checkbox.setAttribute("aria-describedby", "consent-help consent-error");
       }

       function clearError() {
         error.hidden = true;
         error.textContent = "Error: You must agree to the terms of use.";
         checkbox.removeAttribute("aria-invalid");
         checkbox.setAttribute("aria-describedby", "consent-help");
       }

       checkbox.addEventListener("change", () => {
         if (checkbox.checked) {
           clearError();
         }
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         if (!checkbox.checked) {
           status.textContent = "";
           status.removeAttribute("data-state");
           showError("Error: You must agree to the terms of use.");
           checkbox.focus();
           return;
         }

         clearError();
         status.textContent = "Consent saved. You can continue.";
         status.setAttribute("data-state", "success");
       });
     </script>
   </body>
 </html>

